// Generated by Claude Team Kit. Starts every service that has dev.start + dev.url
// in .pipeline/workspace.json, then runs the e2e tests against them.
import { defineConfig, devices } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

type Service = { name: string; type: string; path: string; dev?: { start?: string; url?: string } };

const root = path.resolve(__dirname, '..');
const ws = JSON.parse(fs.readFileSync(path.join(root, '.pipeline/workspace.json'), 'utf8')) as { services: Service[] };
const running = ws.services.filter((s) => s.dev?.start && s.dev?.url);
const web = ws.services.find((s) => s.type === 'frontend' && s.dev?.url);

export default defineConfig({
  testDir: '.',
  timeout: 30_000,
  retries: process.env.CI ? 1 : 0,
  reporter: [['line']],
  use: {
    baseURL: web?.dev?.url,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
  webServer: running.map((s) => ({
    command: s.dev!.start!,
    cwd: path.join(root, s.path),
    url: s.dev!.url!,
    reuseExistingServer: true,
    timeout: 120_000,
  })),
});
